        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">Double-booking usually happens when the calendar is not checking the real calendar where you already have meetings. Always connect your main calendar as a conflict calendar.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Where to Use the Booking Link</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Identify Your Main Calendar</p>
          <p class="text-slate-600 text-sm">Where do you currently track meetings? Google Calendar? Outlook? Apple Calendar?</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Connect Your Calendar</p>
          <p class="text-slate-600 text-sm">In LeadProspectrr, connect your main external calendar to prevent double-booking.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Set as Conflict Calendar</p>
          <p class="text-slate-600 text-sm">Make sure your connected calendar is set as a conflict calendar to block busy times.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">4</div>
        <div>
          <p class="font-semibold text-slate-900">Test the Connection</p>
          <p class="text-slate-600 text-sm">Create a test event on your external calendar and verify it blocks that time in LeadProspectrr.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Connect Calendars and Reduce Double-Booking',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Connect Calendars and Reduce Double-Booking';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Connect Calendars and Reduce Double-Booking

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'connect-calendars' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson connect-calendars not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What usually causes double-booking?', 
    '["Having too many calendars","The calendar not checking your real calendar where you already have meetings","Sending too many reminders","Using a booking link"]'::jsonb,
    'The calendar not checking your real calendar where you already have meetings',
    'Double-booking happens when LeadProspectrr doesn''t know about meetings on your external calendar. Connecting your main calendar as a conflict calendar prevents this.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a conflict calendar?', 
    '["A calendar that creates conflicts","A calendar used to block unavailable times and prevent double-booking","A calendar for arguments","A backup calendar"]'::jsonb,
    'A calendar used to block unavailable times and prevent double-booking',
    'A conflict calendar is an external calendar (like Google or Outlook) that LeadProspectrr checks to block times when you are already busy.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you verify after connecting a calendar?', 
    '["Only the color","Correct calendar connected, right conflict calendar set, busy times blocking, bookings syncing, timezone correct","Nothing, it works automatically","Only the name"]'::jsonb,
    'Correct calendar connected, right conflict calendar set, busy times blocking, bookings syncing, timezone correct',
    'After connecting a calendar, verify: correct calendar is connected, right conflict calendar is set, busy times are blocking slots, bookings sync back, and timezone is correct.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
